import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const root=path.resolve(fileURLToPath(new URL('..',import.meta.url))),mime={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.mjs':'text/javascript; charset=utf-8','.json':'application/json; charset=utf-8','.css':'text/css; charset=utf-8','.png':'image/png','.webp':'image/webp','.jpg':'image/jpeg','.jpeg':'image/jpeg','.woff2':'font/woff2','.ttf':'font/ttf','.mp3':'audio/mpeg','.ogg':'audio/ogg','.wav':'audio/wav'};
export function iconTechniquePreviewServer(){return http.createServer((req,res)=>{try{const url=new URL(req.url,'http://localhost');if(!['GET','HEAD'].includes(req.method)){res.writeHead(405);res.end();return;}const rel=decodeURIComponent(url.pathname==='/'?'/preview/icon-techniques-20261015/':url.pathname);if(!/^\/(assets|css|js|shared|preview)\//.test(rel)){res.writeHead(404);res.end();return;}let file=path.resolve(root,'.'+rel);if(!file.startsWith(root+path.sep)){res.writeHead(403);res.end();return;}if(fs.statSync(file).isDirectory())file=path.join(file,'index.html');const real=fs.realpathSync(file),relative=path.relative(root,real),parts=relative.split(path.sep);if(relative.startsWith('..')||path.isAbsolute(relative)||!['assets','css','js','shared','preview'].includes(parts[0])||parts.some(p=>p.startsWith('.'))){res.writeHead(403);res.end();return;}res.setHeader('Content-Type',mime[path.extname(file)]||'application/octet-stream');res.setHeader('Cache-Control','no-store');if(req.method==='HEAD'){res.end();return;}const stream=fs.createReadStream(real);stream.on("error",()=>{if(!res.headersSent)res.writeHead(404);res.end();});stream.pipe(res);}catch{res.writeHead(404);res.end('not found');}});}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){const port=Number(process.env.ICON_TECHNIQUE_PREVIEW_PORT||4295);iconTechniquePreviewServer().listen(port,'127.0.0.1',()=>console.log(`ICON technique preview: http://127.0.0.1:${port}/preview/icon-techniques-20261015/ · read-only · no database`));}
